mapper.select:
SELECT fs.id, fsd.id AS detailId, fs.code, fs.shop_id AS shopId, fs.shop_name AS shopName, fs.country_id AS countryId, fs.country_name AS countryName, fs.fulfillment_center AS fulfillmentCenter, fs.delivery_status AS deliveryStatus, (SELECT fd.code FROM first_mile_delivery fd INNER Join first_mile_delivery_detail fdd ON fdd.main_id = fd.id AND fdd.is_deleted = FALSE WHERE fdd.fba_shipment_code = fs.code AND fd.is_deleted = FALSE ORDER BY fd.create_time DESC LIMIT 1) AS deliveryCode, fs.platform_shipment_status AS platformShipmentStatus, fs.shipment_create_time AS shipmentCreateTime, fsd.receive_date AS shipmentReceiveTime, fsd.asin, fsd.msku, fsd.fn_sku AS fnSku, fsd.sku_no AS skuNo, fsd.declare_qty AS declareQty, fsd.receive_qty AS receiveQty, fsd.diff_qty AS diffQty, fsd.is_combination AS isCombination, fs.is_packing_download as isPackingDownload, fs.is_sta as isSta FROM fba_shipment_detail fsd INNER JOIN fba_shipment fs ON fs.id = fsd.main_id AND fsd.is_deleted = FALSE WHERE fs.is_deleted = FALSE
and fs.source_type = #{params.sourceType}
AND ${params.sqlMap.default}
${params.permissionSql}
AND fs.id IN
#{item}
AND fsd.id IN
#{item}
ORDER BY
${item.field} ${item.sort}
fs.create_time DESC

SELECT fsd.id, fsd.main_id, fs.code, fs.fulfillment_center, fs.shop_id, fs.shop_name, fs.country_id, fs.country_name, fsd.asin AS asin, fsd.msku AS msku, fsd.fn_sku, fsd.sku_no, fsd.declare_qty, fsd.is_combination FROM fba_shipment_detail fsd INNER JOIN fba_shipment fs ON fs.id = fsd.main_id AND fsd.is_deleted = FALSE WHERE fs.is_deleted = FALSE
and fs.id in
#{id}

SELECT fs.id AS sourceId, fsd.id AS sourceDetailId, fs.code AS sourceCode, fs.shop_id AS channelId, fs.shop_name AS channelName, fs.source_type AS fbaType, fsd.asin, fsd.msku, fsd.fn_sku, fsd.sku_id, fsd.sku_no, fsd.declare_qty FROM fba_shipment_detail fsd INNER JOIN fba_shipment fs ON fs.id = fsd.main_id AND fsd.is_deleted = FALSE WHERE fs.is_deleted = FALSE
and fs.id in
#{id}

SELECT fsd.id as detailId, fs.code, fs.shop_name AS shopName, fs.country_name AS countryName, fs.fulfillment_center AS fulfillmentCenter, fs.delivery_status AS deliveryStatus, (SELECT fd.code FROM first_mile_delivery fd INNER Join first_mile_delivery_detail fdd ON fdd.main_id = fd.id AND fdd.is_deleted = FALSE WHERE fdd.fba_shipment_code = fs.code AND fd.is_deleted = FALSE ORDER BY fd.create_time DESC LIMIT 1) AS deliveryCode, fs.platform_shipment_status AS platformShipmentStatus, fsd.asin, fsd.msku, fsd.fn_sku AS fnSku, fsd.sku_no AS skuNo, fsd.declare_qty AS declareQty, fsd.delivery_qty as deliveryQty, fsd.diff_qty AS diffQty, fs.shipment_create_time AS shipmentCreateTime, fsd.receive_date AS shipmentReceiveTime, fsd.receive_qty AS receiveQty, fs.is_packing_download as isPackingDownload FROM fba_shipment_detail fsd INNER JOIN fba_shipment fs ON fs.id = fsd.main_id AND fsd.is_deleted = FALSE WHERE ${params.sqlMap.default} and fs.is_deleted = FALSE
and fs.source_type = #{params.sourceType}
${params.permissionSql}

select fs.id,fs.code from fba_shipment fs where fs.is_deleted = false

    and fs.code ILIKE concat('%',#{params.code}::text,'%')


    and fs.id = #{params.id}


    and fs.shop_id = #{params.shopId}


    and fs.source_type = #{params.sourceType}

select fs.id as shipmentId, fs.code as shipmentCode, fs.shop_id, fs.shop_name, fs.platform_shipment_status, fsd.id as detailId, fsd.asin, fsd.msku, fsd.fn_sku, fsd.sku_id, fsd.sku_no, fsr.id as receiveId, fsr.declare_qty, fsr.delivery_qty, fsr.diff_qty, fsr.receive_qty, fsr.receive_date, fsr.source_platform from fba_shipment_receive fsr LEFT JOIN fba_shipment_detail fsd on fsd.id = fsr.detail_id and fsd.is_deleted = FALSE LEFT JOIN fba_shipment fs on fs.id = fsd.main_id and fs.is_deleted = FALSE where fsr.is_deleted = FALSE and fsr.receive_date BETWEEN (DATE_TRUNC('month', #{reportMonth})) AND (DATE_TRUNC('month', #{reportMonth}) + INTERVAL '1 month - 1 day')
AND fs.code = #{shipmentCode}
AND fsd.asin = #{asin}
AND fsd.msku = #{msku}

SELECT fs.id, fsd.id AS detailId, fs.code, fse.plan_code AS planCode, fs.shop_id AS shopId, fs.shop_name AS shopName, fs.country_id AS countryId, fs.country_name AS countryName, fs.fulfillment_center AS fulfillmentCenter, fs.delivery_status AS deliveryStatus, (SELECT fd.code FROM first_mile_delivery fd INNER Join first_mile_delivery_detail fdd ON fdd.main_id = fd.id AND fdd.is_deleted = FALSE WHERE fdd.fba_shipment_code = fs.code AND fd.is_deleted = FALSE ORDER BY fd.create_time DESC LIMIT 1) AS deliveryCode, fs.platform_shipment_status AS platformShipmentStatus, fs.shipment_create_time AS shipmentCreateTime, fse.shipment_delivery_time AS shipmentDeliveryTime, fse.delivery_to_warehouse_id AS deliveryToWarehouseId, fse.delivery_to_warehouse_name AS deliveryToWarehouseName, fs.reference_id AS referenceId, fs.create_user_name AS createUserName, fs.remark AS remark, fsd.receive_date AS shipmentReceiveTime, fsd.asin, fsd.msku, fsd.fn_sku AS fnSku, fsd.sku_no AS skuNo, fsd.declare_qty AS declareQty, fsd.receive_qty AS receiveQty, fsd.diff_qty AS diffQty, fsd.is_combination AS isCombination, fsd.box_qty AS boxQty, fsd.per_box_qty AS perBoxQty, fs.is_packing_download as isPackingDownload FROM fba_shipment_detail fsd INNER JOIN fba_shipment fs ON fs.id = fsd.main_id AND fsd.is_deleted = FALSE INNER JOIN fba_shipment_extend fse ON fse.main_id = fsd.main_id AND fse.is_deleted = FALSE WHERE fs.is_deleted = FALSE
and fs.source_type = #{params.sourceType}
AND ${params.sqlMap.default}
${params.permissionSql}
AND fs.id IN
#{item}
AND fsd.id IN
#{item}
ORDER BY
${item.field} ${item.sort}
fs.shipment_create_time DESC

